public int Perimeter(int[,] g) {
    int h = g.GetLength(0), w = g.GetLength(1);
    int land = 0, adj = 0;
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++) {
            if (g[y, x] == 0) continue;
            land++;
            if (x + 1 < w && g[y, x + 1] == 1) adj++;
            if (y + 1 < w && g[y + 1, x] == 1) adj++;
        }
    return 4 * land - 2 * adj;
}

